#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Tesla),
        MagneticField::from_teslas(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Tesla),
        MagneticField::from_base(v).as_teslas()
    );
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Nanotesla),
        MagneticField::from_nanoteslas(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Nanotesla),
        MagneticField::from_base(v).as_nanoteslas()
    );
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Microtesla),
        MagneticField::from_microteslas(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Microtesla),
        MagneticField::from_base(v).as_microteslas()
    );
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Millitesla),
        MagneticField::from_milliteslas(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Millitesla),
        MagneticField::from_base(v).as_milliteslas()
    );
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Gauss),
        MagneticField::from_gausses(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Gauss),
        MagneticField::from_base(v).as_gausses()
    );
    assert_eq!(
        MagneticField::new(v, MagneticFieldUnit::Milligauss),
        MagneticField::from_milligausses(v)
    );
    assert_eq!(
        MagneticField::from_base(v).convert_to(MagneticFieldUnit::Milligauss),
        MagneticField::from_base(v).as_milligausses()
    );
}

#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "T".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Tesla)
    );
    assert_eq!(
        format!("2.5 {}", "T").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Tesla))
    );
    assert_eq!(
        "nT".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Nanotesla)
    );
    assert_eq!(
        format!("2.5 {}", "nT").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Nanotesla))
    );
    assert_eq!(
        "µT".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Microtesla)
    );
    assert_eq!(
        format!("2.5 {}", "µT").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Microtesla))
    );
    assert_eq!(
        "mT".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Millitesla)
    );
    assert_eq!(
        format!("2.5 {}", "mT").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Millitesla))
    );
    assert_eq!(
        "G".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Gauss)
    );
    assert_eq!(
        format!("2.5 {}", "G").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Gauss))
    );
    assert_eq!(
        "mG".parse::<MagneticFieldUnit>(),
        Ok(MagneticFieldUnit::Milligauss)
    );
    assert_eq!(
        format!("2.5 {}", "mG").parse::<MagneticField>(),
        Ok(MagneticField::new(2.5, MagneticFieldUnit::Milligauss))
    );
    assert_eq!(
        "1 not-a-unit".parse::<MagneticField>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = MagneticField::from_base(6.0);
    let b = MagneticField::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = MagneticField::<i64>::from_base(7);
    let b = MagneticField::<i64>::from_base(2);
    assert_eq!(a + b, MagneticField::from_base(9));
    assert_eq!(a % b, MagneticField::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<MagneticField<i64>>(),
        MagneticField::from_base(9)
    );
}
